@media(max-width:600px){.svc-grid{grid-template-columns:1fr}}

/* process */
.proc{background:linear-gradient(180deg,rgba(247,168,10,.05),transparent)}
.proc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;counter-reset:step}
.pstep{position:relative;background:var(--glass);border:1px solid var(--line);border-radius:var(--r);padding:26px 22px;backdrop-filter:blur(12px);transition:transform .2s,border-color .2s}
.pstep:hover{transform:translateY(-5px);border-color:var(--line2)}
.pstep::before{counter-increment:step;content:"0" counter(step);font-family:var(--fdisp);font-weight:800;
  font-size:1rem;color:#04121a;background:linear-gradient(135deg,var(--cyan),#ffb23a);width:44px;height:44px;border-radius:12px;
  display:flex;align-items:center;justify-content:center;margin-bottom:14px;box-shadow:0 0 18px -6px var(--gcyan)}
.pstep.s2::before{background:linear-gradient(135deg,#f7a80a,#f7a80a);color:#fff}
.pstep.s3::before{background:linear-gradient(135deg,#f7a80a,#f7a80a);color:#fff}
.pstep.s4::before{background:linear-gradient(135deg,#f7a80a,#3b82f6);color:#fff}
