/* quote form */
.quote{background:radial-gradient(800px 420px at 88% 0%,rgba(247,168,10,.16),transparent 60%),radial-gradient(700px 400px at 6% 100%,rgba(59,130,246,.14),transparent 60%),linear-gradient(180deg,#080b16,#0b0e1a)}
.qform{background:rgba(10,13,28,.6);border:1px solid var(--line2);border-radius:24px;
  padding:clamp(22px,3vw,36px);max-width:760px;margin:0 auto;box-shadow:var(--shadow);backdrop-filter:blur(18px)}
