.cta .cta-call:hover{transform:translateY(-3px);border-color:var(--amber)}
.cta .cta-call svg{color:var(--amber)}
.cta-char{position:absolute;right:clamp(4px,2vw,44px);bottom:0;height:112%;width:auto;z-index:1;pointer-events:none;
  filter:drop-shadow(0 18px 26px rgba(0,0,0,.5))}
@media(max-width:900px){.cta-copy{max-width:66%}.cta-char{height:106%;right:-14px}}
@media(max-width:660px){.cta-char{display:none}.cta{text-align:center}.cta-copy{max-width:100%}.cta-btns{justify-content:center}.cta p{margin-left:auto;margin-right:auto}}

/* footer */
.ft{background:rgba(6,8,20,.85);color:#9aa3c0;padding:clamp(48px,6vw,76px) 0 0;border-top:1px solid var(--line)}
.ft-top{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr 1fr;gap:30px}
.ft-brand img{height:82px;margin-bottom:18px;filter:drop-shadow(0 0 16px rgba(247,168,10,.35))}
.ft-brand p{font-size:.93rem;max-width:30ch}
.ft-contact{margin-top:16px;display:grid;gap:11px}
.ft-contact a{display:inline-flex;align-items:center;gap:9px;color:#dbe2f5;font-family:var(--fdisp);font-weight:600}
.ft-contact svg{width:16px;height:16px;color:var(--amber)}
.ft-badge{display:inline-flex;align-items:center;gap:10px;color:#dbe2f5;font-family:var(--fdisp);font-weight:600;font-size:.92rem}
.ausflag{width:28px;height:19px;border-radius:4px;overflow:hidden;display:inline-flex;flex-shrink:0;box-shadow:0 0 0 1px var(--line2)}
.ausflag svg{width:28px;height:19px}
.ft-live{display:inline-flex;align-items:center;gap:9px;font-family:var(--fdisp);font-weight:700;font-size:.86rem;color:#a9eec6;
  background:rgba(52,224,161,.1);border:1px solid rgba(52,224,161,.32);padding:6px 13px;border-radius:999px;width:max-content}
.livedot{width:9px;height:9px;border-radius:50%;background:#34e0a1;box-shadow:0 0 0 0 rgba(52,224,161,.55);animation:livep 1.9s infinite}
@keyframes livep{0%{box-shadow:0 0 0 0 rgba(52,224,161,.5)}70%{box-shadow:0 0 0 9px rgba(52,224,161,0)}100%{box-shadow:0 0 0 0 rgba(52,224,161,0)}}
.ft-col h5{font-family:var(--fdisp);font-size:.76rem;letter-spacing:.11em;text-transform:uppercase;color:#fff;margin:0 0 14px}
.ft-col a{display:block;padding:5px 0;font-size:.9rem;transition:.14s}
.ft-col a:hover{color:var(--cyan);padding-left:3px}
.ft-social{display:flex;gap:10px;margin-top:18px}
.ft-social a{width:38px;height:38px;border-radius:10px;background:var(--glass2);border:1px solid var(--line);display:flex;align-items:center;justify-content:center;transition:.16s}
.ft-social a:hover{background:linear-gradient(135deg,var(--cyan),var(--violet));border-color:transparent}
.ft-social svg{width:18px;height:18px;color:#dbe2f5}
.ft-social a:hover svg{color:#04121a}
.ft-bot{margin-top:clamp(34px,5vw,52px);border-top:1px solid var(--line);
  padding:22px 0;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;font-size:.85rem}
.ft-bot .built{display:inline-flex;align-items:center;gap:9px;color:#c6cde3}
.ft-bot .built img{width:26px;height:26px;border-radius:7px}
.ft-bot .built b{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
@media(max-width:1000px){.ft-top{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:640px){.ft-top{grid-template-columns:1fr 1fr}.ft-brand{grid-column:1/-1}}

/* back to top */
.totop{position:fixed;right:20px;bottom:20px;z-index:95;width:50px;height:50px;border-radius:50%;
  background:linear-gradient(135deg,#ffc247,#f7a80a);color:#231704;display:flex;align-items:center;justify-content:center;
  box-shadow:0 0 26px -4px rgba(247,168,10,.6),0 0 40px -8px rgba(247,168,10,.4);transition:transform .18s}
.totop:hover{transform:translateY(-4px)}
.totop svg{width:22px;height:22px}


/* ---------- sticky quote bot (pure CSS) ---------- */
.qbot-tog{position:fixed;opacity:0;pointer-events:none;width:0;height:0}
.qbot-tab{position:fixed;right:0;top:44%;transform:translateY(-50%);z-index:97;
  display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer;
  background:linear-gradient(165deg,#121728,#0a0e1a);border:1px solid var(--line2);border-right:0;
  border-radius:18px 0 0 18px;padding:56px 13px 16px;
  box-shadow:-12px 0 40px -16px rgba(0,0,0,.7),0 0 34px -12px rgba(247,168,10,.45);
  transition:transform .45s cubic-bezier(.6,0,.2,1),box-shadow .2s}
.qbot-tab:hover{box-shadow:-12px 0 46px -14px rgba(0,0,0,.8),0 0 44px -8px rgba(247,168,10,.7)}
.qbot-peek{position:absolute;top:-50px;left:50%;transform:translateX(-50%);width:96px;height:auto;
  filter:drop-shadow(0 10px 14px rgba(0,0,0,.55));animation:botBob 2.8s ease-in-out infinite}
@keyframes botBob{0%,100%{transform:translateX(-50%) translateY(0) rotate(0)}50%{transform:translateX(-50%) translateY(-7px) rotate(-2deg)}}
.qbot-tabtxt{writing-mode:vertical-rl;transform:rotate(180deg);font-family:var(--fdisp);font-weight:800;
  font-size:.72rem;letter-spacing:.13em;text-transform:uppercase;color:#fff;line-height:1}
.qbot-ping{position:absolute;top:-54px;right:6px;width:12px;height:12px;border-radius:50%;background:#34e0a1;
  box-shadow:0 0 0 0 rgba(52,224,161,.6);animation:livep 1.8s infinite}
.qbot-ov{position:fixed;inset:0;background:rgba(4,6,12,.6);backdrop-filter:blur(2px);opacity:0;visibility:hidden;
  z-index:120;transition:opacity .35s,visibility .35s;cursor:pointer}
.qbot-panel{position:fixed;top:0;right:0;height:100%;width:394px;max-width:92vw;z-index:121;
  background:linear-gradient(180deg,#0c1122,#0a0e18);border-left:1px solid var(--line2);
  box-shadow:-30px 0 70px -24px rgba(0,0,0,.85);transform:translateX(100%);visibility:hidden;
  transition:transform .45s cubic-bezier(.6,0,.2,1),visibility .45s;
  display:flex;flex-direction:column;padding:44px 24px 26px;overflow-y:auto;
  -webkit-overflow-scrolling:touch;overscroll-behavior:contain}
.qbot-panel>*{flex:0 0 auto}
.qbot-tog:checked ~ .qbot-panel{transform:translateX(0);visibility:visible}
.qbot-tog:checked ~ .qbot-ov{opacity:1;visibility:visible}
.qbot-tog:checked ~ .qbot-tab{transform:translateY(-50%) translateX(140%)}
.qbot-x{position:absolute;top:14px;right:16px;width:36px;height:36px;border-radius:50%;background:var(--glass2);
  border:1px solid var(--line2);display:flex;align-items:center;justify-content:center;cursor:pointer;
  color:#fff;font-size:1.5rem;line-height:1;transition:.15s}
.qbot-x:hover{border-color:var(--amber);color:var(--amber)}
.qbot-brandrow{display:flex;gap:14px;align-items:center;margin:0 0 14px}
.qbot-av{width:60px;height:60px;border-radius:50%;object-fit:cover;object-position:center;
  background:rgba(255,255,255,.05);border:1px solid rgba(247,168,10,.4);flex-shrink:0;
  box-shadow:0 0 22px -6px rgba(247,168,10,.5)}
.qbot-logo{height:36px;width:auto;filter:drop-shadow(0 0 12px rgba(247,168,10,.3))}
.qbot-greet{margin:0 0 18px}
.qbot-hi{display:block;font-family:var(--fdisp);font-weight:600;font-size:.9rem;color:var(--mut)}
.qbot-brandname{display:block;font-family:var(--fdisp);font-weight:800;font-size:1.35rem;line-height:1.15;
  white-space:nowrap;background:linear-gradient(100deg,#ffe08a,#f7a80a);-webkit-background-clip:text;
  background-clip:text;color:transparent;filter:drop-shadow(0 0 12px rgba(247,168,10,.3))}
.qbot-sub{display:block;font-size:.83rem;color:var(--mut);margin-top:8px}
.qbot-call{display:flex;align-items:center;gap:12px;margin:0 0 16px;padding:11px 14px;border-radius:13px;
  background:rgba(247,168,10,.1);border:1px solid rgba(247,168,10,.32);color:var(--ink);transition:.15s}
.qbot-call:hover{background:rgba(247,168,10,.16);border-color:var(--amber)}
.qbot-callic{width:38px;height:38px;border-radius:50%;background:linear-gradient(135deg,#ffc247,#f7a80a);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.qbot-callic svg{width:17px;height:17px;color:#231704}
.qbot-call small{display:block;font-size:.72rem;color:var(--mut);font-weight:600}
.qbot-call b{font-family:var(--fdisp);font-size:1.02rem;color:var(--ink)}
@media(max-width:420px){.qbot-brandname{font-size:1.15rem}}
.qbot-form{display:grid;gap:12px}
.qbot-form .qb-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.qbot-form .field{min-width:0}
.qbot-form input,.qbot-form select,.qbot-form textarea{width:100%;min-width:0;background:rgba(255,255,255,.05);
  border:1px solid var(--line2);border-radius:11px;padding:12px 13px;color:#fff;font-family:var(--fbody);
  font-size:.92rem;color-scheme:dark}
.qbot-form input::placeholder,.qbot-form textarea::placeholder{color:#7c86a5}
.qbot-form select{color:#c6cde3}
.qbot-form select option{background:#0b0e20;color:#fff}
.qbot-form input:focus,.qbot-form select:focus,.qbot-form textarea:focus{outline:2px solid var(--amber);border-color:transparent}
.qbot-form textarea{resize:vertical;min-height:78px}
.qbot-form button{margin-top:2px;width:100%;justify-content:center}
.qbot-note{text-align:center;color:#7c86a5;font-size:.78rem;margin:12px 0 0}
.qbot-note svg{width:13px;height:13px;vertical-align:-2px;color:#34e0a1}
.qbot-seo{margin-top:18px;border-radius:16px;padding:16px 16px 14px;position:relative;overflow:hidden;
  background:linear-gradient(150deg,rgba(247,168,10,.16),rgba(247,168,10,.05));border:1px solid rgba(247,168,10,.4)}
.qbot-seo::after{content:"";position:absolute;width:180px;height:180px;right:-70px;top:-70px;border-radius:50%;
  background:radial-gradient(circle,rgba(247,168,10,.35),transparent 65%)}
.qbot-seo-badge{position:relative;z-index:1;display:inline-flex;align-items:center;gap:7px;font-family:var(--fdisp);
  font-weight:800;font-size:.7rem;letter-spacing:.06em;text-transform:uppercase;color:#ffd487}
.qbot-seo-badge svg{width:14px;height:14px;color:#ffc247}
.qbot-seo-main{position:relative;z-index:1;display:flex;align-items:center;gap:12px;margin:8px 0 12px}
.qbot-seo-amt{font-family:var(--fdisp);font-weight:800;font-size:2.1rem;line-height:.9;
  background:linear-gradient(100deg,#ffe08a,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 0 14px rgba(247,168,10,.4));animation:pricePulse 2.4s ease-in-out infinite}
.qbot-seo-lbl{font-family:var(--fdisp);font-weight:700;font-size:.86rem;color:#fff;line-height:1.15}
.qbot-seo-list{position:relative;z-index:1;list-style:none;margin:0;padding:0;display:grid;gap:6px}
.qbot-seo-list li{display:flex;align-items:center;gap:8px;font-size:.82rem;color:#dbe2f5;font-weight:500}
.qbot-seo-list li svg{width:15px;height:15px;color:#34e0a1;flex-shrink:0}
@media(max-width:720px){
  .qbot-tab{top:auto;bottom:96px;padding:44px 10px 12px}
  .qbot-peek{width:74px;top:-40px}
  .qbot-tabtxt{font-size:.64rem}
  .qbot-panel{width:100%;max-width:100%;border-left:0;border-top:1px solid var(--line2);border-radius:20px 20px 0 0;top:auto;bottom:0;height:auto;max-height:90vh;max-height:90dvh;padding:30px 20px calc(30px + env(safe-area-inset-bottom,0px));transform:translateY(100%)}
  .qbot-tog:checked ~ .qbot-panel{transform:translateY(0)}
}
@media(prefers-reduced-motion:reduce){.qbot-peek,.qbot-ping{animation:none!important}}
